from rest_framework.exceptions import NotFound


def get_object_or_404(model, **kwargs):
    try:
        return model.objects.get(**kwargs)
    except model.DoesNotExist:
        raise NotFound("منبع مورد نظر پیدا نشد.")


@api_view(["GET"])
def book_detail(request, pk):
    book = get_object_or_404(Book, pk=pk)
    return Response(BookSerializer(book).data)

@api_view(["POST"])
def book_transfer(request, pk):
    book = get_object_or_404(Book, pk=pk)
    to_user_id = request.data.get("to_user")

    if not to_user_id:
        return Response(
            {"to_user": ["این فیلد اجباری است."]},
            status=400,
        )

    try:
        to_user = User.objects.get(pk=to_user_id)
    except User.DoesNotExist:
        return Response(
            {"to_user": ["کاربر پیدا نشد."]},
            status=400,
        )

    if to_user == request.user:
        return Response(
            {"to_user": ["نمی‌توانید به خودتان منتقل کنید."]},
            status=400,
        )

    book.owner = to_user
    book.save(update_fields=["owner"])
    return Response({"status": "transferred", "to": to_user.username})

class TransferSerializer(serializers.Serializer):
    to_user = serializers.PrimaryKeyRelatedField(queryset=User.objects.all())

    def validate_to_user(self, value):
        if value == self.context["request"].user:
            raise serializers.ValidationError("نمی‌توانید به خودتان منتقل کنید.")
        return value


@api_view(["POST"])
def book_transfer(request, pk):
    book = get_object_or_404(Book, pk=pk)
    serializer = TransferSerializer(data=request.data, context={"request": request})
    serializer.is_valid(raise_exception=True)
    to_user = serializer.validated_data["to_user"]
    book.owner = to_user
    book.save(update_fields=["owner"])
    return Response({"status": "transferred"})
